#include <string>
#include "G3D/Rect2D.h"
#include "GLG3D/RenderDevice.h"
using G3D::RenderDevice;
typedef std::string String;
extern const String& __cdecl rendererName();
extern bool __cdecl contains(const String&, const String&);


struct Texture;

struct TextureVTable {
    void (__thiscall* entries[39])(Texture*);
};

struct Texture {
    TextureVTable* vtable;
};

extern Texture* currentTexture;

struct Table {
    unsigned char padding[0x8b];
    bool dirty;
    unsigned char tail[0xA4-0x8c];
    Texture* texture;
    unsigned char gap[4];
    RenderDevice* device;

    void prepare();
    void configure(int, int);
    void apply(unsigned int, int, int);
};

void Table::apply(unsigned int mode, int a, int b)
{
    if (!texture || !device)
        return;

    String renderer(rendererName());

    bool matches;
    { String pattern("MOBILITY RADEON 7500"); matches = contains(renderer, pattern); }
    if (matches) {
        prepare();
        try {
            configure(a, b);
            Texture* selected = texture;
            if (currentTexture != selected) {
                selected->vtable->entries[38](selected);
                currentTexture = selected;
            }
        } catch (...) {
        }
    } else {
        device->notifyResize(a,b);
        RenderDevice* rd=device;
        G3D::Rect2D rect=G3D::Rect2D::xywh(0,0,rd->width(),rd->height());
        device->setViewport(rect);
    }
    dirty=true;
}

