		}

	public:
		const ICreator& getCreator()
		{
			return creator;
		}
		virtual const Name& getClassName() const
		{
			return Name::declare<ClassName>();
		}

	public:
		static const Name& className()
		{
			return Name::declare<ClassName>();
		}
	};

	template<typename DerivedClass, const char* const* ClassName>
