enum eActCtxResult { ActCtxFailed, ActCtxSucceeded, ActCtxNoFusion };
#if (_WIN32_WINNT >= 0x0500) || (_WIN32_FUSION >= 0x0100) || ISOLATION_AWARE_ENABLED

HANDLE AFXAPI AfxCreateActCtxW(PCACTCTXW pActCtx);
