	{
		legacyOffset.reset();

		for (size_t i = 0; i < numChildren(); ++i)
		{
			PVInstance* pvChild = queryTypedChild<PVInstance>((int)i);
			if (pvChild)
				pvChild->clearLegacyOffset();
