		PluginReceiveResult Client::OnReceive(RakPeerInterface* peer, Packet* packet)
		{
			PluginReceiveResult result = PluginInterface::OnReceive(peer, packet);
			if (result != RR_CONTINUE_PROCESSING)
				return result;

			switch(packet->data[0])
			{
			case ID_CONNECTION_REQUEST_ACCEPTED:
				try
				{
					StandardOut::singleton()->print(MESSAGE_INFO, "Connection accepted from %s\n", packet->systemAddress.ToString());
					serverId = packet->systemAddress;

					boost::shared_ptr<Replicator> proxy = Creatable::create<Replicator>(packet->systemAddress, this->rakPeer.get());
					proxy->setParent(reinterpret_cast<Instance*>(reinterpret_cast<char*>(this)+sizeof(Instance)-0x130));

					event_ConnectionAccepted.fire(reinterpret_cast<Instance*>(reinterpret_cast<char*>(this)+sizeof(Instance)-0x130), packet->systemAddress.ToString(), proxy);
				}
				catch (std::exception& e)
				{
					StandardOut::singleton()->print(MESSAGE_ERROR, "Client::OnReceive packet %d: %s", packet->data[0], e.what());
				}
				break;

			case ID_CONNECTION_ATTEMPT_FAILED:
			case ID_NO_FREE_INCOMING_CONNECTIONS:
			case ID_CONNECTION_BANNED:
				try
				{
					StandardOut::singleton()->print(MESSAGE_ERROR, "Failed to connect to %s. %s\n", packet->systemAddress.ToString(), packetName(packet->data[0]));
					reinterpret_cast<FailedEvent*>(&event_ConnectionFailed)->fire(reinterpret_cast<Instance*>(reinterpret_cast<char*>(this)+sizeof(Instance)-0x130), packet->systemAddress.ToString(), packet->data[0], packetName(packet->data[0]));
				}
				catch (std::exception& e)
				{
