				}
				break;

			case ID_INVALID_PASSWORD:
				try
				{
					StandardOut::singleton()->print(MESSAGE_ERROR, "Invalid version from %s", packet->systemAddress.ToString());
					reinterpret_cast<FailedEvent*>(&event_ConnectionFailed)->fire(reinterpret_cast<Instance*>(reinterpret_cast<char*>(this)+sizeof(Instance)-0x130), packet->systemAddress.ToString(), packet->data[0], packetName(packet->data[0]));
					event_ConnectionRejected.fire(reinterpret_cast<Instance*>(reinterpret_cast<char*>(this)+sizeof(Instance)-0x130), packet->systemAddress.ToString());
				}
				catch (std::exception& e)
				{
					StandardOut::singleton()->print(MESSAGE_ERROR, "Client::OnReceive packet %d: %s", packet->data[0], e.what());
