	namespace Network
	{
		char* sPlayer = "Player";

		Player::Player()
			: teamColor(BrickColor::lego_1),
			  neutral(true),
			  under13(false),
			  superSafeChat(false),
			  userId(0),
			  lastActivityTime(0.0)
		{
			Security::Context::current().requirePermission(Security::Administrator, "create a Player");
			setName("Player");
		}

		Player::~Player()
		{
			setCharacter(NULL);
