			//Material(const Material&);
			Material();
			virtual const Level& appendEmptyLevel();
			virtual const Level& appendLevel(G3D::ReferenceCountedPointer<TextureProxy> baseTexture, G3D::Color3 color, float specular, float shiny, float reflect, float transparent);
			virtual const Level& appendLevel(G3D::Color3, float, float, float, float);

